[Collection("NodeApi")] public sealed class Net4bAdminCatalogIntegrationTests
{
 [Fact,Trait("Category","Integration")] public async Task AdminCatalogStoresProductsInventoryPromosAndDelivery_NodeParity(){await using var s=await Scope.OpenAsync();var token=await s.TokenAsync();await Same(await s.Get(s.Node.Client,"/api/admin/catalog/stores",token),await s.Get(s.Dotnet,"/api/admin/catalog/stores",token));await Same(await s.Get(s.Node.Client,"/api/admin/catalog/products",token),await s.Get(s.Dotnet,"/api/admin/catalog/products",token));await Same(await s.Get(s.Node.Client,"/api/admin/catalog/stores/11111111-1111-1111-1111-111111111111/inventory",token),await s.Get(s.Dotnet,"/api/admin/catalog/stores/11111111-1111-1111-1111-111111111111/inventory",token));await Same(await s.Get(s.Node.Client,"/api/admin/catalog/promo-codes",token),await s.Get(s.Dotnet,"/api/admin/catalog/promo-codes",token));await Same(await s.Get(s.Node.Client,"/api/admin/catalog/delivery-settings/11111111-1111-1111-1111-111111111111",token),await s.Get(s.Dotnet,"/api/admin/catalog/delivery-settings/11111111-1111-1111-1111-111111111111",token));}
 [Fact,Trait("Category","Integration")] public async Task AdminCatalogCreateStoreParity(){await using var s=await Scope.OpenAsync();var token=await s.TokenAsync();var suffix=Guid.NewGuid().ToString("N");var n=await s.Post(s.Node.Client,"/api/admin/catalog/stores",new{name="n4b-"+suffix,address="address-"+suffix},token);var d=await s.Post(s.Dotnet,"/api/admin/catalog/stores",new{name="d4b-"+suffix,address="address-"+suffix},token);Assert.Equal(n.StatusCode,d.StatusCode);Assert.Equal(HttpStatusCode.Created,n.StatusCode);using var nj=JsonDocument.Parse(await n.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));using var dj=JsonDocument.Parse(await d.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));Assert.Equal(nj.RootElement.EnumerateObject().Select(x=>x.Name),dj.RootElement.EnumerateObject().Select(x=>x.Name));Assert.Equal(nj.RootElement.GetProperty("store").EnumerateObject().Select(x=>x.Name),dj.RootElement.GetProperty("store").EnumerateObject().Select(x=>x.Name));}
 [Fact,Trait("Category","Integration")] public async Task AdminCatalogCoverageUpsertParity(){await using var s=await Scope.OpenAsync();var token=await s.TokenAsync();var suffix=Guid.NewGuid().ToString("N");foreach(var count in new[]{2,5}){var n=await s.Post(s.Node.Client,"/api/admin/catalog/coverage",new{store_id="11111111-1111-1111-1111-111111111111",address="node-"+suffix,entrance_count=count},token);var d=await s.Post(s.Dotnet,"/api/admin/catalog/coverage",new{store_id="11111111-1111-1111-1111-111111111111",address="dotnet-"+suffix,entrance_count=count},token);Assert.Equal(n.StatusCode,d.StatusCode);using var nj=JsonDocument.Parse(await n.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));using var dj=JsonDocument.Parse(await d.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));Assert.Equal(nj.RootElement.EnumerateObject().Select(x=>x.Name),dj.RootElement.EnumerateObject().Select(x=>x.Name));Assert.Equal(nj.RootElement.GetProperty("coverage").EnumerateObject().Select(x=>x.Name),dj.RootElement.GetProperty("coverage").EnumerateObject().Select(x=>x.Name));}}
 [Fact,Trait("Category","Integration")] public async Task AdminCatalogDeliverySettingsUpsertParity(){await using var s=await Scope.OpenAsync();var token=await s.TokenAsync();var path="/api/admin/catalog/delivery-settings/11111111-1111-1111-1111-111111111111";var n=await s.Put(s.Node.Client,path,new{delivery_fee=777},token);var d=await s.Put(s.Dotnet,path,new{delivery_fee=777},token);Assert.Equal(n.StatusCode,d.StatusCode);using var nj=JsonDocument.Parse(await n.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));using var dj=JsonDocument.Parse(await d.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));Assert.Equal(nj.RootElement.GetProperty("delivery_settings").EnumerateObject().Select(x=>x.Name),dj.RootElement.GetProperty("delivery_settings").EnumerateObject().Select(x=>x.Name));Assert.Equal(nj.RootElement.GetProperty("delivery_settings").GetProperty("delivery_fee").GetRawText(),dj.RootElement.GetProperty("delivery_settings").GetProperty("delivery_fee").GetRawText());}
 [Fact,Trait("Category","Integration")] public async Task AdminCatalogProductCreateUpdateDeleteParity(){await using var s=await Scope.OpenAsync();var token=await s.TokenAsync();var suffix=Guid.NewGuid().ToString("N");var n=await s.Post(s.Node.Client,"/api/admin/catalog/products",new{name="node-"+suffix,category="dairy",unit="pcs",price_per_unit=10,company_price=5,is_weighted=false},token);var d=await s.Post(s.Dotnet,"/api/admin/catalog/products",new{name="dotnet-"+suffix,category="dairy",unit="pcs",price_per_unit=10,company_price=5,is_weighted=false},token);Assert.Equal(n.StatusCode,d.StatusCode);using var nj=JsonDocument.Parse(await n.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));using var dj=JsonDocument.Parse(await d.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));Assert.Equal(nj.RootElement.GetProperty("product").EnumerateObject().Select(x=>x.Name),dj.RootElement.GetProperty("product").EnumerateObject().Select(x=>x.Name));var ni=nj.RootElement.GetProperty("product").GetProperty("id").GetString()!;var di=dj.RootElement.GetProperty("product").GetProperty("id").GetString()!;n=await s.Put(s.Node.Client,"/api/admin/catalog/products/"+ni,new{is_active=false},token);d=await s.Put(s.Dotnet,"/api/admin/catalog/products/"+di,new{is_active=false},token);Assert.Equal(n.StatusCode,d.StatusCode);}
 [Fact,Trait("Category","Integration")] public async Task AdminCatalogInventoryUpsertAndIncomingParity(){await using var s=await Scope.OpenAsync();var token=await s.TokenAsync();var path="/api/admin/catalog/stores/11111111-1111-1111-1111-111111111111/inventory/33333333-3333-3333-3333-333333333333";var n=await s.Put(s.Node.Client,path,new{quantity=7,selling_price=100,is_visible=false},token);var d=await s.Put(s.Dotnet,path,new{quantity=7,selling_price=100,is_visible=false},token);Assert.True(n.StatusCode==d.StatusCode,$"Node: {(int)n.StatusCode} {await n.Content.ReadAsStringAsync(TestContext.Current.CancellationToken)}; .NET: {(int)d.StatusCode} {await d.Content.ReadAsStringAsync(TestContext.Current.CancellationToken)}");using var nj=JsonDocument.Parse(await n.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));using var dj=JsonDocument.Parse(await d.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));Assert.Equal(nj.RootElement.GetProperty("inventory").EnumerateObject().Select(x=>x.Name),dj.RootElement.GetProperty("inventory").EnumerateObject().Select(x=>x.Name));n=await s.Post(s.Node.Client,path+"/incoming",new{quantity=2},token);d=await s.Post(s.Dotnet,path+"/incoming",new{quantity=2},token);Assert.Equal(n.StatusCode,d.StatusCode);}
 [Fact,Trait("Category","Integration")] public async Task AdminCatalogStoreUpdateAndSoftDeleteParity(){await using var s=await Scope.OpenAsync();var t=await s.TokenAsync();var suffix=Guid.NewGuid().ToString("N");var n=await s.Post(s.Node.Client,"/api/admin/catalog/stores",new{name="node-"+suffix,address="a"+suffix},t);var d=await s.Post(s.Dotnet,"/api/admin/catalog/stores",new{name="dotnet-"+suffix,address="a"+suffix},t);using var nj=JsonDocument.Parse(await n.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));using var dj=JsonDocument.Parse(await d.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));var np=nj.RootElement.GetProperty("store").GetProperty("id").GetString()!;var dp=dj.RootElement.GetProperty("store").GetProperty("id").GetString()!;n=await s.Put(s.Node.Client,"/api/admin/catalog/stores/"+np,new{status="paused"},t);d=await s.Put(s.Dotnet,"/api/admin/catalog/stores/"+dp,new{status="paused"},t);Assert.Equal(n.StatusCode,d.StatusCode);n=await s.Delete(s.Node.Client,"/api/admin/catalog/stores/"+np,t);d=await s.Delete(s.Dotnet,"/api/admin/catalog/stores/"+dp,t);Assert.Equal(n.StatusCode,d.StatusCode);using var nd=JsonDocument.Parse(await n.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));using var dd=JsonDocument.Parse(await d.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));Assert.Equal(nd.RootElement.GetProperty("store").EnumerateObject().Select(x=>x.Name),dd.RootElement.GetProperty("store").EnumerateObject().Select(x=>x.Name));Assert.Equal("inactive",dd.RootElement.GetProperty("store").GetProperty("status").GetString());}
 [Fact,Trait("Category","Integration")] public async Task AdminCatalogProductSoftDeleteAndPromoCrudParity(){await using var s=await Scope.OpenAsync();var t=await s.TokenAsync();var suffix=Guid.NewGuid().ToString("N");var n=await s.Post(s.Node.Client,"/api/admin/catalog/products",new{name="node-"+suffix,category="fruit",unit="pcs",price_per_unit=10,company_price=5,is_weighted=false},t);var d=await s.Post(s.Dotnet,"/api/admin/catalog/products",new{name="dotnet-"+suffix,category="fruit",unit="pcs",price_per_unit=10,company_price=5,is_weighted=false},t);using var nj=JsonDocument.Parse(await n.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));using var dj=JsonDocument.Parse(await d.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));n=await s.Delete(s.Node.Client,"/api/admin/catalog/products/"+nj.RootElement.GetProperty("product").GetProperty("id").GetString(),t);d=await s.Delete(s.Dotnet,"/api/admin/catalog/products/"+dj.RootElement.GetProperty("product").GetProperty("id").GetString(),t);Assert.Equal(n.StatusCode,d.StatusCode);var code="P"+suffix[..12];n=await s.Post(s.Node.Client,"/api/admin/catalog/promo-codes",new{code,discount_type="fixed_amount",discount_value=50},t);d=await s.Post(s.Dotnet,"/api/admin/catalog/promo-codes",new{code="D"+suffix[..12],discount_type="fixed_amount",discount_value=50},t);Assert.Equal(n.StatusCode,d.StatusCode);using var pn=JsonDocument.Parse(await n.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));using var pd=JsonDocument.Parse(await d.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));Assert.Equal(pn.RootElement.GetProperty("promo_code").EnumerateObject().Select(x=>x.Name),pd.RootElement.GetProperty("promo_code").EnumerateObject().Select(x=>x.Name));var ni=pn.RootElement.GetProperty("promo_code").GetProperty("id").GetString()!;var di=pd.RootElement.GetProperty("promo_code").GetProperty("id").GetString()!;n=await s.Put(s.Node.Client,"/api/admin/catalog/promo-codes/"+ni,new{is_active=false},t);d=await s.Put(s.Dotnet,"/api/admin/catalog/promo-codes/"+di,new{is_active=false},t);Assert.Equal(n.StatusCode,d.StatusCode);n=await s.Delete(s.Node.Client,"/api/admin/catalog/promo-codes/"+ni,t);d=await s.Delete(s.Dotnet,"/api/admin/catalog/promo-codes/"+di,t);Assert.Equal(n.StatusCode,d.StatusCode);}
 [Fact,Trait("Category","Integration")] public async Task AdminCatalogAuthorizationAndValidationParity(){await using var s=await Scope.OpenAsync();var path="/api/admin/catalog/products";foreach(var email in new[]{"manager@koz.kz","admin@koz.kz","customers@koz.kz"}){var t=await s.TokenAsync(email);var n=await s.Get(s.Node.Client,path,t);var d=await s.Get(s.Dotnet,path,t);await Same(n,d);}var admin=await s.TokenAsync();var bad=new{ name="",category="wrong",unit="bad",price_per_unit=-1,company_price=-1,is_weighted="no"};await Same(await s.Post(s.Node.Client,path,bad,admin),await s.Post(s.Dotnet,path,bad,admin));await Same(await s.Put(s.Node.Client,"/api/admin/catalog/stores/not-a-uuid/inventory/not-a-uuid",new{quantity=1},admin),await s.Put(s.Dotnet,"/api/admin/catalog/stores/not-a-uuid/inventory/not-a-uuid",new{quantity=1},admin));}
 [Fact,Trait("Category","Integration")] public async Task AdminCatalogConcurrencyParity(){await using var s=await Scope.OpenAsync();var t=await s.TokenAsync();for(var i=0;i<5;i++){var suffix=Guid.NewGuid().ToString("N");var store=new{name="concurrent-"+suffix,address="address-"+suffix};Assert.Equal(await Parallel(()=>s.Post(s.Node.Client,"/api/admin/catalog/stores",store,t)),await Parallel(()=>s.Post(s.Dotnet,"/api/admin/catalog/stores",new{name="dotnet-"+suffix,address="address-"+suffix},t)));var coverage="coverage-"+suffix;Assert.Equal(await Parallel(()=>s.Post(s.Node.Client,"/api/admin/catalog/coverage",new{store_id="11111111-1111-1111-1111-111111111111",address=coverage,entrance_count=1},t)),await Parallel(()=>s.Post(s.Dotnet,"/api/admin/catalog/coverage",new{store_id="11111111-1111-1111-1111-111111111111",address="dotnet-"+coverage,entrance_count=1},t)));var code="N"+suffix[..12];var n=await Parallel(()=>s.Post(s.Node.Client,"/api/admin/catalog/promo-codes",new{code,discount_type="fixed_amount",discount_value=1},t));var d=await Parallel(()=>s.Post(s.Dotnet,"/api/admin/catalog/promo-codes",new{code="D"+suffix[..12],discount_type="fixed_amount",discount_value=1},t));Assert.Equal(n,d);Assert.Contains(HttpStatusCode.Conflict,n);Assert.Contains(HttpStatusCode.Created,n);var path="/api/admin/catalog/stores/11111111-1111-1111-1111-111111111111/inventory/33333333-3333-3333-3333-333333333333";Assert.Equal(await Parallel(()=>s.Put(s.Node.Client,path,new{quantity=7,selling_price=10,is_visible=false},t)),await Parallel(()=>s.Put(s.Dotnet,path,new{quantity=9,selling_price=11,is_visible=true},t)));}}
 static async Task<HttpStatusCode[]> Parallel(Func<Task<HttpResponseMessage>> send){using var barrier=new Barrier(2);var tasks=Enumerable.Range(0,2).Select(_=>Task.Run(async()=>{barrier.SignalAndWait();using var response=await send();return response.StatusCode;}));return (await Task.WhenAll(tasks)).Order().ToArray();}
 static async Task Same(HttpResponseMessage n,HttpResponseMessage d){Assert.Equal(n.StatusCode,d.StatusCode);Assert.Equal(await n.Content.ReadAsStringAsync(TestContext.Current.CancellationToken),await d.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));}
 private sealed class Scope: IAsyncDisposable{readonly Net1ApiFactory f;Scope(Net1ApiFactory f,HttpClient d,NodeAuthServer n){this.f=f;Dotnet=d;Node=n;}public HttpClient Dotnet{get;}public NodeAuthServer Node{get;}public static async Task<Scope> OpenAsync(){var cs=Environment.GetEnvironmentVariable("KOZ_NET4B_TEST_CONNECTION_STRING");if(string.IsNullOrWhiteSpace(cs))throw SkipException.ForSkip("Set KOZ_NET4B_TEST_CONNECTION_STRING.");Assert.Equal("koz_dotnet_net4b_test",new NpgsqlConnectionStringBuilder(cs).Database);var f=new Net1ApiFactory(cs);return new(f,f.CreateClient(),await NodeAuthServer.StartAsync(cs,TestContext.Current.CancellationToken));}public async Task<string> TokenAsync(string email="catalog@koz.kz"){var r=await Dotnet.PostAsJsonAsync("/api/auth/staff/login",new{email,password="Manager123"},TestContext.Current.CancellationToken);Assert.Equal(HttpStatusCode.OK,r.StatusCode);using var j=JsonDocument.Parse(await r.Content.ReadAsStringAsync(TestContext.Current.CancellationToken));return j.RootElement.GetProperty("token").GetString()!;}public Task<HttpResponseMessage> Get(HttpClient c,string path,string t){var q=new HttpRequestMessage(HttpMethod.Get,path);q.Headers.Authorization=new AuthenticationHeaderValue("Bearer",t);return c.SendAsync(q,TestContext.Current.CancellationToken);}public Task<HttpResponseMessage> Post(HttpClient c,string path,object b,string t){var q=new HttpRequestMessage(HttpMethod.Post,path){Content=JsonContent.Create(b)};q.Headers.Authorization=new AuthenticationHeaderValue("Bearer",t);return c.SendAsync(q,TestContext.Current.CancellationToken);}public Task<HttpResponseMessage> Put(HttpClient c,string path,object b,string t){var q=new HttpRequestMessage(HttpMethod.Put,path){Content=JsonContent.Create(b)};q.Headers.Authorization=new AuthenticationHeaderValue("Bearer",t);return c.SendAsync(q,TestContext.Current.CancellationToken);}public Task<HttpResponseMessage> Delete(HttpClient c,string path,string t){var q=new HttpRequestMessage(HttpMethod.Delete,path);q.Headers.Authorization=new AuthenticationHeaderValue("Bearer",t);return c.SendAsync(q,TestContext.Current.CancellationToken);}public ValueTask DisposeAsync(){Node.Dispose();Dotnet.Dispose();f.Dispose();return ValueTask.CompletedTask;}}
}
